import "scheduler" for Scheduler
import "timer" for Timer

// A fiber that sleeps, and while sleeping, another fiber schedules a shorter
// sleep. The shorter one must resolve first.
Scheduler.add {
  Timer.sleep(50)
  System.print("long")
}

Scheduler.add {
  Timer.sleep(10)
  System.print("short")
}

System.print("main")
Timer.sleep(100)
System.print("done")

// expect: main
// expect: short
// expect: long
// expect: done
